CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    CREATE TABLE "Proyectos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(150) NOT NULL,
        "Descripcion" character varying(1000),
        "FechaInicio" timestamp with time zone NOT NULL,
        "FechaFin" timestamp with time zone,
        CONSTRAINT "PK_Proyectos" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    CREATE TABLE "Tareas" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Titulo" character varying(150) NOT NULL,
        "Descripcion" character varying(1000),
        "Estado" character varying(30) NOT NULL,
        "Prioridad" character varying(30) NOT NULL,
        "FechaLimite" timestamp with time zone NOT NULL,
        "ProyectoId" integer NOT NULL,
        CONSTRAINT "PK_Tareas" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Tareas_Proyectos_ProyectoId" FOREIGN KEY ("ProyectoId") REFERENCES "Proyectos" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    CREATE INDEX "IX_Tareas_Estado_Prioridad" ON "Tareas" ("Estado", "Prioridad");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    CREATE INDEX "IX_Tareas_FechaLimite" ON "Tareas" ("FechaLimite");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    CREATE INDEX "IX_Tareas_ProyectoId" ON "Tareas" ("ProyectoId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261125214459_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261125214459_InitialCreate', '10.0.15');
    END IF;
END $EF$;
COMMIT;

